	/**************************************************************************
     * Event : scwin.grdData1_ontoggleclick
     * 기 능 : 그리드 토클 버튼 클릭 이벤트
     **************************************************************************/		
	scwin.grdData1_ontoggleclick = function() {
		grdData1.mergeClear();
		scwin.gridMergeCol();
	}

	/**************************************************************************
     * Event : scwin.toggle_onchange
     * 기 능 : 토글 스위치 버튼 이벤트
     **************************************************************************/	
	scwin.toggle_onchange = function(){
		if(toggle1.getValue() == "open"){
			grdData1.mergeClear();
			grdData1.spanAll( true );
			scwin.gridMergeCol();
		} else if(toggle1.getValue() == "close"){
			grdData1.mergeClear();
			grdData1.spanAll( false );
			scwin.gridMergeCol();
		}
	}

