    /**************************************************************************
     * [5] 사용자정의 함수
     **************************************************************************/

    /***************************************************************************
     * 함 수 명: scwin.grdSearch
     * 기    능:   조회
     ***************************************************************************/
    scwin.grdSearch = function(){

    	var rows = dcdataList1.getRowCount();
    	for (var i=0; i<rows; i++) {

    		if(i == 0){
    			txtBudgetSq.setValue( dcdataList1.getCellData( i , "budgetSq" ));	
    		}

			if(dcdataList1.getCellData( i , "gubun" ) == "1") {
				grdData1.setRowBackgroundColor( i , "#F8FBB9" );
				grdData1.setRowStyle( i , "font-weight", "bold");
				grdData1.setRowStyle( i , "color", "#8000FF");
    		}
    	}
		grdData1.spanAll(false);
		grdData1.toggle(dcdataList1.getCellData( dcdataList1.getMatchedIndex( "cstrUcdNm" , scwin.cstrUcdNm , true) , "rowNum" )-1);
    	scwin.gridMergeCol();
    };

    /***************************************************************************
     * 함수명 : scwin.gridMergeCol
     * 기능 : 그리드 컬럼 병합
     ***************************************************************************/
    scwin.gridMergeCol = function() {
    	grdData1.mergeClear();
		grdData1.mergeCol( 0 , true );
		grdData1.mergeCol( 1 , true );
		grdData1.mergeCol( 2 , true );
		grdData1.mergeCol( 3 , true );
		grdData1.mergeCol( 4 , true );
		grdData1.mergeCol( 5 , true );
		grdData1.mergeCol( 6 , true );
		grdData1.mergeCol( 7 , false );
		grdData1.mergeCol( 8 , false );
		grdData1.mergeCol( 9 , false );
		grdData1.mergeCol( 10 , false );
		grdData1.mergeByCol( );
		//grdData1.mergeClear();
		//grdData1.mergeByRestricCol();
    };

	scwin.checkVal = function() {
		return WebSquare.wUnit.getDomById('grdData1_cell_4_4').getAttribute('rowspan') == 2;
	}	
	scwin.unitTest = function() {
		//init
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('grdData1_cell_1_4').querySelector('span').click()");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
		WebSquare.wUnit.addCommand("pause", "300");		

		//Run  and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}
	scwin.unitTest();
